  if(j.assignment){html+='<section class="card iw-card"><h2>'+esc(({pending:'Job offer',accepted:'Job accepted',declined:'Job declined'})[j.assignment.status])+'</h2><p>'+esc(j.assignment.status==='pending'?'Check the date, agreed pay and materials, then reply.':j.assignment.status==='accepted'?'The installer has accepted this job.':'The installer declined: '+(j.assignment.note||''))+'</p>'+(this.user.role==='installer'?'<p>Agreed pay: <strong>'+esc(money(j.installerPay?.[this.user.id]?.amount||0))+'</strong> · Left to pay: '+esc(money(installerPaymentSummary(j,this.user.id).balance))+'</p>':'')+(this.user.role==='installer'&&j.assignment.status==='pending'?button('data-iw-accept','Accept job',true)+button('data-iw-decline','Decline job'):'')+'</section>';if(this.user.role==='installer'&&j.assignment.status!=='accepted')return html;}

  if(j.status==='Completed'||j.clientReview)html+=clientReviewPanel(j,this.user);
  if(this.user.role==='installer'&&j.status==='Needs correction'&&j.clientReview?.outcome==='fixes')html+='<section class="card iw-card"><form data-iw-form="clientFix"><h2>Record the client fix</h2><p>Start and finish the fix visit. Add a new photo, then send this same job back to Operations.</p>'+field('note','What did you fix?',j.clientFix?.reviewAt===j.clientReview.at?j.clientFix.note:'','textarea')+this.upload('demo','Take a photo of the fix')+'<p class="helper">'+j.evidence.filter(e=>e.kind==='demo'&&!e.cameraId&&!(j.clientReview.evidenceBefore||[]).includes(e.id)).length+' new fix photos added.</p><button class="btn btn-primary">Save client fix</button></form></section>';
  const progress=installationProgress(j),step=this.jobStep||'cameras';
  html+='<section class="card iw-card"><h2>'+esc(j.status==='Submitted'?'Sent to Operations':j.status==='Completed'?'Installation checks approved':'Finish this job')+'</h2><p>'+esc(j.status==='Submitted'?(supervisor?'Check the photos and materials. Then approve the job or ask for a fix.':'Your checks and photos have been sent. Operations will review this job.'):j.status==='Completed'?'The installation checks are approved. The assigned site supervisor handles client sign-off.':'Work through these three steps. Your work stays on this job.')+'</p><div class="iw-steps" aria-label="Installation steps">'+[['cameras',supervisor?'1. Cameras & photos':'1. Camera checks',progress.camerasDone+' / '+progress.camerasTotal+' checked'],['materials',supervisor?'2. Materials & returns':'2. Materials left',progress.materialsDone+' / '+progress.materialsTotal+' counted'],['finish',supervisor?'3. Review & approve':'3. Finish & send',j.status==='Submitted'?'Waiting for approval':j.status==='Completed'?'Approved':progress.missing.length?'Checks still needed':'Ready to send']].map(([key,label,status])=>'<button type="button" class="btn '+(step===key?'btn-primary':'btn-ghost')+'" data-iw-step="'+key+'" aria-pressed="'+(step===key)+'">'+esc(label)+'<small>'+esc(status)+'</small></button>').join('')+'</div></section>';
  const pay=this.paymentView(j);if(pay)html+='<section class="card iw-card"><details><summary>'+(supervisor?'Installer pay and payments':'Your pay and balance')+'</summary>'+pay+'</details></section>';
